INSERT INTO movie_credits (movie_id, person_id, credit_type, job, display_order) SELECT m.id, p.id, 'WRITER', 'Screenplay', 0 FROM movies m, people p WHERE m.slug = 'roma-2018' AND p.name = 'Alfonso Cuarón' ON CONFLICT DO NOTHING;
INSERT INTO movie_credits (movie_id, person_id, credit_type, character_name, display_order) SELECT m.id, p.id, 'CAST', NULL, 0 FROM movies m, people p WHERE m.slug = 'roma-2018' AND p.name = 'Yalitza Aparicio' ON CONFLICT DO NOTHING;
INSERT INTO movie_credits (movie_id, person_id, credit_type, character_name, display_order) SELECT m.id, p.id, 'CAST', NULL, 1 FROM movies m, people p WHERE m.slug = 'roma-2018' AND p.name = 'Marina de Tavira' ON CONFLICT DO NOTHING;
